<?php
session_start();

function db(){
  static $p=null;
  if($p) return $p;
  $h=getenv('DB_HOST')?:'127.0.0.1';
  $pt=getenv('DB_PORT')?:'3306';
  $n=getenv('DB_NAME')?:'datasell';
  $u=getenv('DB_USER')?:'root';
  $pw=getenv('DB_PASS')?:'';
  $p=new PDO("mysql:host=$h;port=$pt;dbname=$n;charset=utf8mb4",$u,$pw,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
  return $p;
}
function initdb(){
  try{
    $p=db();
    $p->exec("CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fullname VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,phone VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,wallet_balance DECIMAL(14,2) NOT NULL DEFAULT 0,is_admin TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
    CREATE TABLE IF NOT EXISTS transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,type VARCHAR(50) NOT NULL,amount DECIMAL(14,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'successful',reference VARCHAR(80) NOT NULL UNIQUE,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB;
    CREATE TABLE IF NOT EXISTS funding_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reference VARCHAR(80) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
  }catch(Throwable $e){ return false; }
  return true;
}
initdb();
function me(){
  if(empty($_SESSION['uid'])) return null;
  $s=db()->prepare('SELECT id,fullname,email,phone,wallet_balance,is_admin FROM users WHERE id=?');
  $s->execute([$_SESSION['uid']]);
  return $s->fetch();
}
function ref($p='TX'){ return $p.'-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(3))); }
function esc($s){ return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8'); }
function money($n){ return '₦'.number_format((float)$n,2); }
function icon($name){
  $icons=['home'=>'⌂','dashboard'=>'⌂','data'=>'▦','airtime'=>'◉','bills'=>'⚡','exam'=>'◆','wallet'=>'₦','transactions'=>'↔','profile'=>'●','admin'=>'▣','api'=>'</>','shield'=>'✓','arrow'=>'→','menu'=>'☰'];
  return $icons[$name]??'•';
}

$action=$_POST['action']??'';$msg='';$err='';
try{
  if($action==='register'){
    if(strlen($_POST['password']??'')<6) throw new Exception('Password must be at least 6 characters.');
    $s=db()->prepare('INSERT INTO users(fullname,email,phone,password_hash) VALUES(?,?,?,?)');
    $s->execute([trim($_POST['fullname']),strtolower(trim($_POST['email'])),preg_replace('/\D/','',$_POST['phone']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);
    $_SESSION['uid']=db()->lastInsertId(); header('Location: ?page=dashboard'); exit;
  }
  if($action==='login'){
    $s=db()->prepare('SELECT * FROM users WHERE email=?'); $s->execute([strtolower(trim($_POST['email']))]); $user=$s->fetch();
    if(!$user||!password_verify($_POST['password'],$user['password_hash'])) throw new Exception('Invalid email or password.');
    $_SESSION['uid']=$user['id']; header('Location: ?page=dashboard'); exit;
  }
  if($action==='logout'){ session_destroy(); header('Location: /'); exit; }
  if($action==='fund'){
    $user=me(); if(!$user) throw new Exception('Please sign in.');
    $a=(float)($_POST['amount']??0); if($a<100) throw new Exception('Minimum funding request is ₦100.');
    db()->prepare('INSERT INTO funding_requests(user_id,amount,reference) VALUES(?,?,?)')->execute([$user['id'],$a,ref('FUND')]);
    $msg='Funding request submitted for admin verification.';
  }
  if($action==='buy'){
    $user=me(); if(!$user) throw new Exception('Please sign in.');
    $a=(float)($_POST['amount']??0); if($a<=0||$a>$user['wallet_balance']) throw new Exception('Insufficient wallet balance.');
    $type=$_POST['type']??'service'; $p=db(); $p->beginTransaction();
    $p->prepare('UPDATE users SET wallet_balance=wallet_balance-? WHERE id=?')->execute([$a,$user['id']]);
    $p->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$user['id'],$type,$a,'successful',ref(),json_encode(['provider'=>$_POST['provider']??'','recipient'=>$_POST['recipient']??''])]);
    $p->commit(); $msg='Demo transaction recorded successfully. Live fulfillment requires a provider API.';
  }
  if($action==='approve'&&me()&&me()['is_admin']){
    $id=(int)($_POST['id']??0); $p=db(); $p->beginTransaction();
    $s=$p->prepare("SELECT * FROM funding_requests WHERE id=? AND status='pending' FOR UPDATE"); $s->execute([$id]); $r=$s->fetch();
    if(!$r) throw new Exception('Request not found.');
    $p->prepare("UPDATE funding_requests SET status='approved' WHERE id=?")->execute([$id]);
    $p->prepare('UPDATE users SET wallet_balance=wallet_balance+? WHERE id=?')->execute([$r['amount'],$r['user_id']]);
    $p->prepare('INSERT INTO transactions(user_id,type,amount,status,reference) VALUES(?,?,?,?,?)')->execute([$r['user_id'],'wallet_funding',$r['amount'],'successful',$r['reference']]);
    $p->commit(); $msg='Wallet funded successfully.';
  }
}catch(Throwable $e){ $err=$e->getMessage(); }

