<div class="page-intro"><div><span class="eyebrow">Account</span><h2>Your profile</h2><p>Review your account information and access level.</p></div></div><div class="profile-grid"><div class="panel profile-identity"><div class="profile-avatar-lg"><?=strtoupper(substr($u['fullname'],0,1))?></div><h3><?=esc($u['fullname'])?></h3><p><?=esc($u['email'])?></p><span class="status success">Active account</span></div><div class="panel profile-details"><h3>Account details</h3><div class="detail-row"><span>Full name</span><b><?=esc($u['fullname'])?></b></div><div class="detail-row"><span>Email</span><b><?=esc($u['email'])?></b></div><div class="detail-row"><span>Phone</span><b><?=esc($u['phone'])?></b></div><div class="detail-row"><span>Account role</span><b><?= $u['is_admin']?'Administrator':'Customer' ?></b></div></div></div>

<?php elseif($page==='admin'&&$u['is_admin']): $rs=db()->query("SELECT f.*,u.email,u.fullname FROM funding_requests f JOIN users u ON u.id=f.user_id ORDER BY f.id DESC LIMIT 100"); $funding=$rs->fetchAll(); $userCount=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(); $txCount=(int)db()->query('SELECT COUNT(*) FROM transactions')->fetchColumn(); $pending=(int)db()->query("SELECT COUNT(*) FROM funding_requests WHERE status='pending'")->fetchColumn(); $volume=(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE status='successful'")->fetchColumn(); ?>
<div class="page-intro"><div><span class="eyebrow">Administration</span><h2>Operations console</h2><p>Monitor customers, transaction activity and funding approvals.</p></div></div><div class="admin-stats"><div class="stat-card"><span>Total users</span><strong><?=number_format($userCount)?></strong><small>Registered accounts</small></div><div class="stat-card"><span>Transactions</span><strong><?=number_format($txCount)?></strong><small>All recorded activity</small></div><div class="stat-card"><span>Pending funding</span><strong><?=number_format($pending)?></strong><small>Needs review</small></div><div class="stat-card"><span>Transaction volume</span><strong><?=money($volume)?></strong><small>Recorded successful value</small></div></div><div class="section-row"><h3>Funding requests</h3><span><?=count($funding)?> records</span></div><div class="panel table-panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>Customer</th><th>Reference</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$funding): ?><tr><td colspan="5"><div class="empty-state"><span>₦</span><b>No funding requests</b><small>New requests will appear here.</small></div></td></tr><?php else: foreach($funding as $r): ?><tr><td><div><b><?=esc($r['fullname'])?></b><small class="block-muted"><?=esc($r['email'])?></small></div></td><td class="muted-cell"><?=esc($r['reference'])?></td><td><b><?=money($r['amount'])?></b></td><td><span class="status <?= $r['status']==='approved'?'success':'pending' ?>"><?=esc(ucfirst($r['status']))?></span></td><td><?php if($r['status']==='pending'): ?><form method="post"><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small btn-primary">Approve</button></form><?php else: ?><span class="muted-cell">Completed</span><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<?php endif; ?>
</section></main><nav class="mobile-bottom-nav"><?php foreach(['dashboard'=>'Home','data'=>'Data','airtime'=>'Airtime','wallet'=>'Wallet','profile'=>'Profile'] as $k=>$v): ?><a class="<?= $page===$k?'active':'' ?>" href="?page=<?=$k?>"><span><?=icon($k)?></span><small><?=$v?></small></a><?php endforeach; ?></nav></div>
